import assert from "node:assert/strict";
const defaults = Object.freeze({ version: 1, theme: "light", fontSize: 16 });

export function parsePreferences(raw) {
  if (typeof raw !== "string" || raw.length > 2048) return null;
  try {
    const value = JSON.parse(raw);
    if (!value || typeof value !== "object" || Array.isArray(value) || value.version !== 1) return null;
    if (!["light", "dark"].includes(value.theme) || !Number.isInteger(value.fontSize) || value.fontSize < 12 || value.fontSize > 24) return null;
    return { version: 1, theme: value.theme, fontSize: value.fontSize };
  } catch { return null; }
}
export function readPreferences(storage) {
  try { return parsePreferences(storage.getItem("editor-preferences")) ?? { ...defaults }; }
  catch { return { ...defaults }; }
}
const memory = { getItem: () => '{"version":1,"theme":"dark","fontSize":18,"plan":"expert"}' };
console.log(JSON.stringify(readPreferences(memory)));
console.log(JSON.stringify(readPreferences({ getItem: () => "broken json" })));
assert.equal(parsePreferences('{"version":2,"theme":"dark","fontSize":18}'), null);
assert.equal(parsePreferences('{"version":1,"theme":"dark","fontSize":99}'), null);
assert.deepEqual(readPreferences({ getItem: () => { throw new Error("Storage disabled"); } }), defaults);
assert.equal("plan" in readPreferences(memory), false);

