const order = [];
const step = (label) => order.push(label);

step("sync:start");
Promise.resolve().then(() => {
  step("microtask:then-1");
  Promise.resolve().then(() => step("microtask:nested-in-then-1"));
});
queueMicrotask(() => step("microtask:queued"));
setTimeout(() => {
  step("timer:1");
  Promise.resolve().then(() => step("microtask:after-timer-1"));
  setTimeout(() => {
    step("timer:scheduled-inside-timer-1");
    setTimeout(() => {
      step("timer:final");
      console.log(order.join("\n"));
      assert.ok(order.indexOf("sync:start") < order.indexOf("sync:end"));
      assert.ok(order.indexOf("sync:end") < order.indexOf("microtask:then-1"));
      assert.ok(order.indexOf("microtask:then-1") < order.indexOf("microtask:queued"));
      assert.ok(order.indexOf("microtask:queued") < order.indexOf("microtask:nested-in-then-1"));
      assert.ok(order.indexOf("microtask:nested-in-then-1") < order.indexOf("timer:1"));
      assert.ok(order.indexOf("timer:1") < order.indexOf("microtask:after-timer-1"));
      assert.ok(order.indexOf("microtask:after-timer-1") < order.indexOf("timer:2"));
      assert.ok(order.indexOf("timer:2") < order.indexOf("timer:scheduled-inside-timer-1"));
      assert.ok(order.indexOf("timer:scheduled-inside-timer-1") < order.indexOf("timer:final"));
      assert.equal(order.length, 10);
    }, 0);
  }, 0);
}, 0);
setTimeout(() => step("timer:2"), 0);
step("sync:end");

