import assert from "node:assert/strict";

const lines = [];
const settle = (label, promise) =>
  promise.then(value => lines.push(label + " -> " + value), error => lines.push(label + " -> Error: " + error.message));

const ok = (value) => Promise.resolve(value);
const fail = (message) => Promise.reject(new Error(message));

// 1. Promise.all: first rejection wins, other results are lost.
try { await Promise.all([ok(1), fail("E2"), ok(3)]); }
catch (error) { lines.push("all -> Error: " + error.message); }

// 2. Promise.allSettled: every outcome is kept for reporting.
const settled = await Promise.allSettled([ok(1), fail("E2"), ok(3)]);
lines.push("allSettled -> " + settled.map(r => r.status === "fulfilled" ? "ok:" + r.value : "err:" + r.reason.message).join(","));

// 3. Promise.race: the first settlement wins, even a rejection.
try { await Promise.race([fail("E1"), ok(2)]); }
catch (error) { lines.push("race -> Error: " + error.message); }

// 4. Promise.any: first fulfillment wins, rejections are skipped.
lines.push("any -> " + (await Promise.any([fail("E1"), ok(2), ok(3)])));

// 5. Promise.any with only rejections raises AggregateError.
try { await Promise.any([fail("A"), fail("B")]); }
catch (error) {
  assert.ok(error instanceof AggregateError);
  lines.push("anyAllFailed -> Error: " + error.errors.map(e => e.message).join(","));
}

// 6. A caught error lets the chain continue with a recovery value.
const recovered = await ok(1).then(v => { throw new Error("boom:" + v); }).catch(error => 42).then(v => v + 1);
lines.push("recovered -> " + recovered);

// 7. Throwing inside .then skips the next .then and reaches .catch.
const skipped = await ok("a").then(() => { throw new Error("skip"); }).then(() => "never").catch(error => "caught:" + error.message);
lines.push("skipped -> " + skipped);

console.log(lines.join("\n"));

assert.equal(settled.length, 3);
assert.equal(settled.filter(r => r.status === "rejected").length, 1);
assert.equal(recovered, 43);
assert.equal(skipped, "caught:skip");

