import assert from "node:assert/strict";

const lines = [];
const say = (value) => lines.push(String(value));

function* naturals() {
  let n = 0;
  for (;;) yield n++;
}
function* take(count, source) {
  let left = count;
  const iterator = source[Symbol.iterator]();
  while (left > 0) {
    const next = iterator.next();
    if (next.done) return;
    left -= 1;
    yield next.value;
  }
  iterator.return?.();
}
function* map(fn, source) {
