// Observable stand-in for an event bus: listener counts, not GC internals.
class Bus {
  #listeners = new Map();
  on(name, listener) {
    const set = this.#listeners.get(name) ?? new Set();
    set.add(listener);
    this.#listeners.set(name, set);
    return () => this.off(name, listener);
  }
  off(name, listener) { this.#listeners.get(name)?.delete(listener); }
  emit(name, payload) { for (const listener of this.#listeners.get(name) ?? []) listener(payload); }
  count(name) { return this.#listeners.get(name)?.size ?? 0; }
}

// Leaky widget: every render subscribes again, and the closure keeps each id alive.
function createLeakyWidget(bus) {
  return function render(id) {
    bus.on("update", () => "stale-render:" + id);
  };
}

// Fixed widget: one subscription, a dispose handle, no per-render retention.
function createFixedWidget(bus) {
  let latestId = null;
  const dispose = bus.on("update", () => "fresh-render:" + latestId);
  return {
    render(id) { latestId = id; },
    dispose,
  };
}

const bus = new Bus();
const leaky = createLeakyWidget(bus);
for (let id = 1; id <= 3; id += 1) leaky(id);
say("leaky listeners: " + bus.count("update"));

