fixed.render(1);
fixed.render(2);
fixed.render(3);
say("with fixed active: " + bus.count("update"));
fixed.dispose();
say("after fixed dispose: " + bus.count("update"));

// Unbounded cache vs capped cache: size stays observable and bounded.
function createCappedCache(limit) {
  const map = new Map();
  return {
    get(key) { return map.get(key); },
    set(key, value) {
      map.set(key, value);
      if (map.size > limit) map.delete(map.keys().next().value);
      return value;
    },
    get size() { return map.size; },
  };
}
const cache = createCappedCache(3);
for (let i = 0; i < 5; i += 1) cache.set("k" + i, i);
say("capped cache size: " + cache.size + ", oldest evicted: " + !cache.get("k0"));

// WeakMap holds per-node metadata without keeping nodes alive.
const metadata = new WeakMap();
const liveNode = { id: "n1" };
metadata.set(liveNode, { touched: 1 });
say("weakmap live node: " + metadata.has(liveNode) + ", exposes size: " + (metadata.size === undefined));

console.log(lines.join("\n"));

assert.equal(bus.count("update"), 3);
assert.equal(cache.size, 3);
assert.equal(metadata.has(liveNode), true);

