import assert from "node:assert/strict";

// Fake clock: deterministic time control without real timers.
function createClock() {
  let now = 0;
  let handle = 0;
  const tasks = new Map();
  return {
    now: () => now,
    setTimeout(fn, ms) { handle += 1; tasks.set(handle, { at: now + ms, fn }); return handle; },
    clearTimeout(id) { tasks.delete(id); },
    advance(ms) {
      const target = now + ms;
      for (;;) {
        let dueId = null;
        let dueAt = Infinity;
        for (const [id, task] of tasks) if (task.at <= target && task.at < dueAt) { dueAt = task.at; dueId = id; }
        if (dueId === null) break;
        const task = tasks.get(dueId);
        tasks.delete(dueId);
        now = task.at;
        task.fn();
      }
      now = target;
    },
  };
}

function debounce(fn, waitMs, clock) {
  let timerId = null;
  return (...args) => {
    if (timerId !== null) clock.clearTimeout(timerId);
    timerId = clock.setTimeout(() => { timerId = null; fn(...args); }, waitMs);
  };
}

function throttle(fn, intervalMs, clock) {
  let lastCall = null;
  let timerId = null;
  return (...args) => {
    const elapsed = lastCall === null ? Infinity : clock.now() - lastCall;
    if (elapsed >= intervalMs) {
      lastCall = clock.now();
      fn(...args);
    } else if (timerId === null) {
      timerId = clock.setTimeout(() => {
        timerId = null;
        lastCall = clock.now();
        fn(...args);
      }, intervalMs - elapsed);
    }
  };
}

function memoize(fn, keyOf = JSON.stringify) {
  const cache = new Map();
  const wrapped = (value) => {
    const key = keyOf(value);
    if (!cache.has(key)) cache.set(key, fn(value));
    return cache.get(key);
  };
  wrapped.cache = cache;
  return wrapped;
}

const lines = [];
const clock = createClock();

// Debounce: a burst of 5 keystrokes collapses into one trailing save.
let saves = 0;
const save = debounce((text) => { saves += 1; lines.push("saved:" + text); }, 300, clock);
for (const text of ["j", "ja", "jav", "java", "javascript"]) { save(text); clock.advance(100); }
clock.advance(300);
lines.push("saves:" + saves);

// Throttle: a burst of scroll events is capped, with a guaranteed trailing call.
let paints = 0;
const paint = throttle((y) => { paints += 1; lines.push("paint:" + y); }, 200, clock);
for (let y = 0; y < 5; y += 1) { paint(y); clock.advance(80); }
clock.advance(200);
lines.push("paints:" + paints);

// Memoize: repeated expensive inputs hit the cache; the counter proves it.
let computed = 0;
const slowSquare = memoize((n) => { computed += 1; return n * n; });
const results = [slowSquare(12), slowSquare(12), slowSquare(10), slowSquare(12), slowSquare(10)];
lines.push("results:" + results.join(","));
lines.push("computed:" + computed);

console.log(lines.join("\n"));

assert.equal(saves, 1);
assert.equal(paints, 3);
assert.deepEqual(results, [144, 144, 100, 144, 100]);
assert.equal(computed, 2);

