import assert from "node:assert/strict";

const waits = [];
const sleep = async (ms) => { waits.push(ms); };
const makeJitter = (spreadMs) => { let n = 0; return () => { n = (n + 1) % 3; return n * spreadMs; }; };
const jitter = makeJitter(10);

class TransientError extends Error {}

// Scripted loader: deterministic outcomes, no network.
function createScriptedSource(script) {
  const calls = new Map();
  return async (page) => {
    const index = calls.get(page) ?? 0;
    calls.set(page, index + 1);
    const step = script[page][Math.min(index, script[page].length - 1)];
    if (!step.ok) throw new TransientError(step.status);
    return step.rows;
  };
}

async function loadPage(source, page, { attempts, baseMs, capMs }) {
  for (let attempt = 0; ; attempt++) {
    try {
      const rows = await source(page);
      return { page, attempts: attempt + 1, rows };
    } catch (error) {
      if (attempt + 1 >= attempts || !(error instanceof TransientError)) throw error;
      await sleep(Math.min(baseMs * 2 ** attempt, capMs) + jitter());
    }
  }
}

const REGIONS = new Set(["north", "south"]);
function validateRow(row, page, index) {
  const problems = [];
  if (!row || typeof row.id !== "string" || !row.id.startsWith("r")) problems.push("id must be a string starting with r");
  if (!REGIONS.has(row.region)) problems.push("unknown region " + JSON.stringify(row.region));
  if (typeof row.amount !== "number" || !Number.isFinite(row.amount) || row.amount < 0) problems.push("amount must be a finite number >= 0");
  return problems.map(text => "row " + page + "#" + index + ": " + text);
}

function aggregate(rows) {
  const byRegion = new Map();
  for (const row of rows) {
    const current = byRegion.get(row.region) ?? { region: row.region, count: 0, total: 0 };
    byRegion.set(row.region, { ...current, count: current.count + 1, total: current.total + row.amount });
  }
  return [...byRegion.values()].sort((a, b) => (a.region < b.region ? -1 : 1));
}

const script = {
  p1: [
    { ok: false, status: "HTTP 503" },
    { ok: true, rows: [{ id: "r1", region: "north", amount: 100 }, { id: "r2", region: "south", amount: 30 }, { id: "r3", region: "north", amount: 140 }] },
