// Day 15 — TypeScript for the JavaScript developer.
// JSDoc annotations describe contracts for the static checker, but at runtime
// the types are erased: explicit runtime validation is still required.
import assert from "node:assert/strict";

/** @typedef {Object} Money
 *  @property {number} amount
 *  @property {"RUB"|"USD"|"EUR"} currency
 */

/** @param {Money} money @returns {string} */
function formatMoney({ amount, currency }) {
  if (typeof amount !== "number" || !Number.isFinite(amount)) {
    throw new TypeError("amount must be a finite number");
  }
  if (!["RUB", "USD", "EUR"].includes(currency)) {
    throw new TypeError("unknown currency: " + String(currency));
  }
  return amount.toFixed(2) + " " + currency;
}

assert.equal(formatMoney({ amount: 1299.5, currency: "RUB" }), "1299.50 RUB");
console.log(formatMoney({ amount: 1299.5, currency: "RUB" }));
try {
  formatMoney({ amount: "1299.5", currency: "RUB" }); // the checker sees this, node does not
} catch (error) {
  console.log(error.constructor.name + ": " + error.message);
}

const stages = [
  { file: "money.js", checked: "no" },
  { file: "money.js + @ts-check + JSDoc", checked: "statically" },
  { file: "money.ts", checked: "statically" },
];
for (const stage of stages) console.log(stage.file + " -> checked " + stage.checked);
console.log("erased at runtime:", typeof 1299.5, typeof "RUB");

// A typedef describes a shape; the runtime guard mirrors it field by field.
/** @typedef {Object} Port
 *  @property {number} value
 */
/** @param {Port} port @returns {number} */
function normalizePort({ value }) {
  if (!Number.isInteger(value) || value < 1 || value > 65535) {
    throw new RangeError("port out of range");
  }
  return value;
}
assert.throws(() => normalizePort({ value: 99999 }), RangeError);
console.log(normalizePort({ value: 8080 }), normalizePort({ value: 443 }));

