// Day 16 — Classes and prototypes in depth.
// Prototype chain, super, private fields, detached this, and a closure factory.
import assert from "node:assert/strict";

class Counter {
  #total = 0;
  static kind() { return "Counter"; }
  increment(step = 1) { this.#total += step; return this.#total; }
  get total() { return this.#total; }
}

class BoundedCounter extends Counter {
  constructor(limit) { super(); this.limit = limit; }
  increment(step = 1) { return Math.min(super.increment(step), this.limit); }
}

const counter = new BoundedCounter(3);
assert.equal(counter.total, 0);
console.log("steps:", [counter.increment(), counter.increment(), counter.increment(), counter.increment()].join(" "));
console.log("instanceof:", counter instanceof BoundedCounter, counter instanceof Counter);
console.log("static via subclass:", BoundedCounter.kind());

const chain = [];
for (let p = Object.getPrototypeOf(counter); p && p !== Object.prototype; p = Object.getPrototypeOf(p)) {
  chain.push(p.constructor.name);
}
console.log("chain:", chain.join(" -> "));

// Detached method: `this` is lost. Only the error class is printed, never rely
// on the exact message text across engines.
class Tally {
  total = 0;
  bump() { this.total += 1; return this.total; }
}
const tally = new Tally();
const detached = tally.bump;
try { detached(); } catch (error) { console.log("detached:", error.constructor.name); }
const bound = tally.bump.bind(tally);
console.log("bound:", bound(), bound(), "tally=" + tally.total);

// When a class is not needed: one closure per instance, no `this` at all.
function makeAccumulator() {
  let sum = 0;
  return { add: (n) => (sum += n), value: () => sum };
}
const acc = makeAccumulator();
acc.add(5); acc.add(7);
console.log("closure accumulator:", acc.value());

