// Day 17 — Immutability and structural copying.
// Spread is shallow, structuredClone is deep, freezing is one level deep.
import assert from "node:assert/strict";

const original = Object.freeze({ id: 7, tags: ["a", "b"], meta: { depth: 2 } });

// 1. Spread creates a new shell, but nested objects are shared.
const shallow = { ...original, id: 8 };
assert.equal(shallow.meta, original.meta);
shallow.meta.depth = 99; // meta itself is not frozen -> the original changes too
console.log("shallow shares meta:", shallow.meta === original.meta, "original.meta.depth:", original.meta.depth);
assert.equal(original.meta.depth, 99);

// 2. structuredClone copies the whole structure; frozen-ness is not preserved.
const deep = structuredClone(original);
assert.notEqual(deep, original);
deep.meta.depth = 5;
deep.tags.push("c");
console.log("deep independent:", deep.meta.depth, original.meta.depth, deep.tags.join("+"), original.tags.join("+"));
console.log("frozen flag: source=" + Object.isFrozen(original), "clone=" + Object.isFrozen(deep));

// 3. Copy only what changes: per-item spread in a list update.
const list = Object.freeze([{ id: 1, done: false }, { id: 2, done: false }, { id: 3, done: false }]);
const updated = list.map((item) => (item.id === 2 ? { ...item, done: true } : item));
console.log("list update:", JSON.stringify(updated));
console.log("untouched items shared:", updated[0] === list[0], "changed item new:", updated[1] !== list[1]);

// 4. Copy cost grows with structure size: one clone per save, not per keystroke.
let copies = 0;
function saveSnapshot(state) { copies += 1; return structuredClone(state); }
const state = { board: [[1, 2], [3, 4]] };
const a = saveSnapshot(state); state.board[0][0] = 9; const b = saveSnapshot(state);
console.log("snapshots independent:", a.board[0][0], b.board[0][0], "copies:", copies);

