// Day 18 — WeakMap, WeakRef and cache retention.
// Weak keys do not keep their owners alive; reclamation timing is not observable.
import assert from "node:assert/strict";

const weak = new WeakMap();
const user = { id: 1, name: "Ada" };
weak.set(user, { visits: 3 });
assert.equal(weak.has(user), true);
console.log("metadata:", JSON.stringify(weak.get(user)));

// Only objects (and registered symbols) can be keys; primitives are rejected.
try { weak.set("Ada", {}); } catch (error) { console.log("primitive key:", error.constructor.name); }

// No size, no iteration: the registry must not pin its keys.
console.log("no enumeration:", weak.size, typeof weak.forEach, typeof weak.keys);

// WeakRef holds a target weakly; while we keep a strong reference, deref works.
let session = { token: "abc" };
const ref = new WeakRef(session);
console.log("strong ref alive:", ref.deref() === session, ref.deref()?.token);

// Drop the strong reference, but never assert reclamation: gc timing is not
// deterministic, so the demo records intent instead of observing collection.
session = null;
console.log("strong ref dropped:", session === null, "weak ref may return object or undefined");

// Deterministic part of weak collections: explicit delete and lookup.
const stale = { id: 2 };
weak.set(stale, { visits: 0 });
weak.delete(stale);
console.log("after delete:", weak.has(stale), weak.has(user));

// WeakMap as per-object TTL registry for the LRU cache of day 23.
const ttlByObject = new WeakMap();
function touchMetadata(object, ttlMs) { ttlByObject.set(object, { ttlMs, touched: true }); }
touchMetadata(user, 30_000);
console.log("ttl registry:", JSON.stringify(ttlByObject.get(user)), "unknown:", ttlByObject.get({ id: 9 }));

