// Day 19 — The iterator protocol.
// Symbol.iterator, manual next(), lazy chains, early close via finally.
import assert from "node:assert/strict";

class Range {
  constructor(from, to) { this.from = from; this.to = to; }
  *[Symbol.iterator]() {
    for (let n = this.from; n <= this.to; n += 1) yield n;
  }
}

const range = new Range(1, 4);
const it = range[Symbol.iterator]();
assert.equal(it.next().value, 1);
console.log("manual next:", it.next().value, it.next().value, "done=" + it.next().done);
console.log("spread:", [...range].join(","));

// Lazy operators: nothing runs until the consumer pulls.
function mapIter(source, fn) {
  return { *[Symbol.iterator]() { for (const v of source) yield fn(v); } };
}
function filterIter(source, predicate) {
  return { *[Symbol.iterator]() { for (const v of source) if (predicate(v)) yield v; } };
}
const pipeline = filterIter(mapIter(new Range(1, 10), (n) => n * n), (n) => n % 3 === 0);
console.log("lazy pipeline:", [...pipeline].join(","));

// break calls .return() on the generator, which runs the finally block.
let closedAt = null;
function* naturals() {
  try {
    let n = 1;
    while (true) yield n++;
  } finally {
    closedAt = "closed";
  }
}
const taken = [];
for (const n of naturals()) {
  taken.push(n);
  if (n === 3) break;
}
console.log("taken:", taken.join(","), "generator:", closedAt);

// A hand-written iterator with its own return() to mirror the generator.
function countedRange(from, to) {
  let returned = false;
  const values = [];
  for (let n = from; n <= to; n += 1) values.push(n);
  return {
    taken: values.length,
    [Symbol.iterator]() {
      let i = 0;
      return {
        next: () => (i < values.length ? { value: values[i++], done: false } : { value: undefined, done: true }),
        return: (value) => { returned = true; return { value, done: true }; },
      };
    },
    get closedEarly() { return returned; },
  };
}
const counted = countedRange(1, 1_000_000);
for (const v of counted) break;
console.log("hand-written:", "taken=" + counted.taken, "closedEarly=" + counted.closedEarly);

