// Day 20 — Async iterators and async generators.
// for await...of, Symbol.asyncIterator, batching. All awaits are microtasks,
// so the trace is fully deterministic without timers.
import assert from "node:assert/strict";

const trace = [];

async function* source(items) {
  for (const item of items) {
    await Promise.resolve(); // stand-in for I/O; keeps ordering deterministic
    trace.push("produce " + item);
    yield item;
  }
}

// Consumes any async iterable and yields fixed-size batches.
async function* batches(items, size) {
  let buffer = [];
  for await (const item of items) {
    buffer.push(item);
    if (buffer.length === size) { yield buffer; buffer = []; }
  }
  if (buffer.length > 0) yield buffer;
}

const collected = [];
for await (const batch of batches(source([1, 2, 3, 4, 5, 6, 7]), 3)) {
  trace.push("consume [" + batch.join("+") + "]");
  collected.push(batch);
}
assert.deepEqual(collected, [[1, 2, 3], [4, 5, 6], [7]]);
console.log(collected.map((b) => "[" + b.join("+") + "]").join(" "));

// A custom async iterable without a generator function.
const ticker = {
  ticks: 3,
  async *[Symbol.asyncIterator]() {
    for (let i = 1; i <= this.ticks; i += 1) { await Promise.resolve(); yield "tick-" + i; }
  },
};
const ticks = [];
for await (const t of ticker) ticks.push(t);
console.log(ticks.join(" "));

// Errors thrown inside an async generator propagate to the consumer.
async function* failing() {
  yield "ok-1";
  throw new Error("upstream gone");
}
const seen = [];
try {
  for await (const item of failing()) seen.push(item);
} catch (error) {
  seen.push("caught: " + error.message);
}
console.log(seen.join(" | "));
console.log("trace: " + trace.length + " events, deterministic order");

