// Day 21 — Worker threads: an introduction.
// Workers run parallel JS; data is copied (structured clone) or transferred.
import assert from "node:assert/strict";
import { Worker } from "node:worker_threads";

// The worker script is a CommonJS string (eval: true) so the demo is one file.
const squaresSource = `
const { parentPort, workerData } = require("node:worker_threads");
for (const n of workerData.numbers) {
  parentPort.postMessage({ input: n, square: n * n });
}
`;

const numbers = [2, 3, 5, 7, 11];
const squaresWorker = new Worker(squaresSource, { eval: true, workerData: { numbers } });
const squares = [];
squaresWorker.on("message", (message) => squares.push(message));
await new Promise((resolve) => squaresWorker.on("exit", resolve));
squares.sort((a, b) => a.input - b.input); // collect in task order, not arrival order
console.log(squares.map((r) => r.input + "^2=" + r.square).join(" "));
assert.deepEqual(squares.map((r) => r.square), [4, 9, 25, 49, 121]);

// postMessage copies: the worker sees the value as it was at send time.
const echoSource = `
const { parentPort } = require("node:worker_threads");
parentPort.on("message", (message) => parentPort.postMessage({ seen: message.label, len: message.items.length }));
`;
const echoWorker = new Worker(echoSource, { eval: true });
const echoDone = new Promise((resolve) => echoWorker.on("message", resolve));
const payload = { label: "before", items: [1, 2] };
echoWorker.postMessage(payload);
payload.label = "after"; // mutates only the main-thread copy
const echo = await echoDone;
console.log("worker saw:", echo.seen, "items=" + echo.len, "main sees:", payload.label);
await echoWorker.terminate(); // a live message listener keeps the worker referenced

// Transfer instead of copy: the ArrayBuffer is detached in the sender.
const transferSource = `
const { parentPort } = require("node:worker_threads");
parentPort.on("message", (message) => parentPort.postMessage(message.length));
`;
const transferWorker = new Worker(transferSource, { eval: true });
const lengthPromise = new Promise((resolve) => transferWorker.on("message", resolve));
const bytes = new Uint8Array([1, 2, 3]);
transferWorker.postMessage(bytes, [bytes.buffer]);
const workerLength = await lengthPromise;
console.log("detached in main:", bytes.byteLength === 0, "worker length:", workerLength);
await transferWorker.terminate();

