// Day 22 — Streams: an introduction.
// Readable -> Transform -> Writable with pipeline(), and async iteration.
import assert from "node:assert/strict";
import { Readable, Transform, Writable } from "node:stream";
import { pipeline } from "node:stream/promises";

const collected = [];
const sink = new Writable({
  write(chunk, encoding, callback) { collected.push(chunk.toString()); callback(); },
});

const upper = new Transform({
  transform(chunk, encoding, callback) {
    this.push(chunk.toString().toUpperCase());
    callback();
  },
});

const words = ["alpha", "beta", "gamma"];
await pipeline(Readable.from(words), upper, sink);
console.log("pipeline result:", collected.join("|"));
assert.deepEqual(collected, ["ALPHA", "BETA", "GAMMA"]);

// Streams are async-iterable: for await pulls chunk by chunk.
const chunks = [];
for await (const chunk of Readable.from(["ab", "cd", "ef"])) chunks.push(chunk.toString());
console.log("for await:", chunks.join("-"));

// A transform can change granularity: three numbers become one aggregate.
const summing = new Transform({
  objectMode: true,
  transform(chunk, encoding, callback) {
    this.total = (this.total ?? 0) + chunk;
    callback();
  },
  flush(callback) { this.push(this.total); callback(); },
});
const totals = [];
await pipeline(Readable.from([10, 20, 30, 40]), summing, new Writable({
  objectMode: true,
  write(chunk, encoding, callback) { totals.push(chunk); callback(); },
}));
console.log("aggregated total:", totals.join(","));

