// Day 23 — Cache and invalidation: TTL + LRU on Map with an injected clock.
// Map preserves insertion order, which makes the LRU trick possible.
import assert from "node:assert/strict";

class TtlLruCache {
  constructor({ capacity, ttlMs, now }) {
    assert(Number.isInteger(capacity) && capacity > 0, "capacity");
    assert(ttlMs > 0, "ttlMs");
    this.capacity = capacity;
    this.ttlMs = ttlMs;
    this.now = now;
    this.entries = new Map(); // key -> { value, storedAt }
    this.stats = { hits: 0, misses: 0, evictions: 0, expired: 0 };
  }

  get(key) {
    const entry = this.entries.get(key);
    if (!entry) { this.stats.misses += 1; return undefined; }
    if (this.now() - entry.storedAt >= this.ttlMs) {
      this.entries.delete(key);
      this.stats.expired += 1;
      this.stats.misses += 1;
      return undefined;
    }
    this.entries.delete(key); // re-insert to mark the key as most recently used
    this.entries.set(key, entry);
    this.stats.hits += 1;
    return entry.value;
  }

  set(key, value) {
    if (this.entries.has(key)) this.entries.delete(key);
    else if (this.entries.size === this.capacity) {
      const oldest = this.entries.keys().next().value;
      this.entries.delete(oldest);
      this.stats.evictions += 1;
    }
    this.entries.set(key, { value, storedAt: this.now() });
  }

  has(key) { return this.entries.has(key) && this.now() - this.entries.get(key).storedAt < this.ttlMs; }
}

const clock = { t: 0, now: () => clock.t, advance: (ms) => { clock.t += ms; } };
const cache = new TtlLruCache({ capacity: 2, ttlMs: 100, now: clock.now });
const log = [];

cache.set("a", 1); log.push("set a=1");
cache.set("b", 2); log.push("set b=2");
log.push("get a -> " + cache.get("a") + " (hit, a is now freshest)");
cache.set("c", 3); log.push("set c=3 (evicts least-recently-used b)");
log.push("get b -> " + cache.get("b"));
clock.advance(120); log.push("clock +120ms (past ttl=100)");
log.push("get a -> " + cache.get("a") + " (expired)");
cache.set("d", 4); log.push("set d=4");
log.push("has c -> " + cache.has("c"), "has d -> " + cache.has("d"));
console.log(log.join("\n"));
assert.deepEqual(cache.stats, { hits: 1, misses: 2, evictions: 1, expired: 1 });
console.log("stats:", JSON.stringify(cache.stats));

