// Day 24 — Regular expressions in practice.
// Named groups, anchors, matchAll, functional replace, and ReDoS hygiene.
import assert from "node:assert/strict";

// 1. Parse a log line with named groups; anchors keep parsing strict.
const pattern = /^(?<time>\S+) (?<level>DEBUG|INFO|WARN|ERROR) (?<service>\w+) (?<message>.+)$/;
const line = "2026-05-14T09:30:02Z WARN payments retry 3 of 5 took 812ms";
const match = line.match(pattern);
assert.equal(match.groups.level, "WARN");
console.log(match.groups.time, match.groups.level, match.groups.service);
console.log("message:", match.groups.message);
console.log("no match:", "garbage line".match(pattern));

// 2. Validate with anchored patterns; without ^...$ a match anywhere counts.
const slug = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
console.log("slugs:", slug.test("user-profile-7"), slug.test("-bad-"), slug.test("ok-slug"));

// 3. matchAll for repeated captures; always escape user text in replacements.
const csv = "ada=3,bo=5,cy=2";
const scores = [...csv.matchAll(/(?<name>[a-z]+)=(?<score>\d+)/g)];
console.log("scores:", scores.map((m) => m.groups.name + ":" + m.groups.score).join(" "));
const sum = scores.reduce((total, m) => total + Number(m.groups.score), 0);
console.log("sum:", sum);

const escapeHtml = (text) => text.replace(/[<>&]/g, (ch) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;" })[ch]);
console.log(escapeHtml("<b>Tom & Jerry</b>"));

// 4. ReDoS hygiene: nested quantifiers like (\w+)+ backtrack explosively.
const risky = /^(\w+)+$/; // never run unbounded on user input
console.log("risky pattern on a small safe input:", risky.test("abc123"));
console.log("hygiene: bound the input length, prefer atomic shapes, anchor patterns");

