const Ok = (value) => ({ ok: true, value });
const Err = (error) => ({ ok: false, error });

function parseAmount(input) {
  const n = Number(input);
  if (!Number.isFinite(n) || n <= 0) return Err("amount must be a positive number");
  return Ok(n);
}

function fromThrowable(fn) {
  try { return Ok(fn()); } catch (error) { return Err(error.message); }
}

function unwrap(result) {
  if (result.ok) return result.value;
  throw new Error(result.error);
}

function run(raw) {
  return unwrap(parseAmount(raw));
}

console.log(run("150"));        // 150
console.log(parseAmount("-5"));  // { ok: false, error: ... }

// Day 26 — Configuration and environment.
// One loader: defaults, profile overrides, typed parsing of process.env.
import assert from "node:assert/strict";

const PROFILES = {
  development: { logLevel: "debug", retries: 1 },
  production: { logLevel: "info", retries: 3 },
};
const LOG_LEVELS = ["trace", "debug", "info", "warn", "error"];

function loadConfig(env, profile) {
  if (!(profile in PROFILES)) throw new RangeError("unknown profile: " + profile);
  const resolved = { port: 3000, host: "127.0.0.1", ...PROFILES[profile] };
  if (env.PORT !== undefined) {
    const port = Number(env.PORT);
    if (!Number.isInteger(port) || port < 1 || port > 65535) throw new RangeError("PORT must be an integer 1..65535");
    resolved.port = port;
  }
  if (env.HOST !== undefined) {
    if (!env.HOST.trim()) throw new TypeError("HOST must be a non-empty string");
    resolved.host = env.HOST.trim();
  }
  if (env.LOG_LEVEL !== undefined) {
    if (!LOG_LEVELS.includes(env.LOG_LEVEL)) throw new RangeError("LOG_LEVEL must be one of " + LOG_LEVELS.join("|"));
    resolved.logLevel = env.LOG_LEVEL;
  }
  if (env.RETRIES !== undefined) {
    const retries = Number(env.RETRIES);
    if (!Number.isInteger(retries) || retries < 0 || retries > 10) throw new RangeError("RETRIES must be an integer 0..10");
    resolved.retries = retries;
  }
  return Object.freeze(resolved);
}

const development = loadConfig({ PORT: "8080", LOG_LEVEL: "trace" }, "development");
const production = loadConfig({ PORT: "443", HOST: "0.0.0.0" }, "production");
console.log("development:", JSON.stringify(development));
console.log("production:", JSON.stringify(production));
assert.throws(() => loadConfig({ PORT: "99999" }, "production"), RangeError);
assert.throws(() => loadConfig({ LOG_LEVEL: "loud" }, "production"), RangeError);
try { loadConfig({ PORT: "http" }, "development"); } catch (error) { console.log(error.constructor.name + ": " + error.message); }
console.log("frozen:", Object.isFrozen(development), "defaults kept: retries=" + development.retries);

