    if (!Number.isInteger(retries) || retries < 0 || retries > 10) throw new RangeError("RETRIES must be an integer 0..10");
    resolved.retries = retries;
  }
  return Object.freeze(resolved);
}

const development = loadConfig({ PORT: "8080", LOG_LEVEL: "trace" }, "development");
const production = loadConfig({ PORT: "443", HOST: "0.0.0.0" }, "production");
console.log("development:", JSON.stringify(development));
console.log("production:", JSON.stringify(production));
assert.throws(() => loadConfig({ PORT: "99999" }, "production"), RangeError);
assert.throws(() => loadConfig({ LOG_LEVEL: "loud" }, "production"), RangeError);
try { loadConfig({ PORT: "http" }, "development"); } catch (error) { console.log(error.constructor.name + ": " + error.message); }
console.log("frozen:", Object.isFrozen(development), "defaults kept: retries=" + development.retries);

