// Day 27 — JavaScript security basics.
// Prototype pollution, safe merging, and dependency hygiene.
import assert from "node:assert/strict";

const FORBIDDEN = ["__proto__", "constructor", "prototype"];

// Forgiving merge: unknown dangerous keys are skipped and reported.
function safeMerge(target, source) {
  const out = { ...target };
  const skipped = [];
  for (const key of Object.keys(source)) {
    if (FORBIDDEN.includes(key)) { skipped.push(key); continue; }
    out[key] = source[key]; // own keys only, no prototype walk
  }
  return { merged: out, skipped };
}

// Strict merge: a dangerous key aborts the operation.
function strictMerge(target, source) {
  const { merged } = safeMerge(target, source);
  for (const key of Object.keys(source)) {
    if (FORBIDDEN.includes(key)) throw new TypeError("forbidden key: " + key);
  }
  return merged;
}

const payload = JSON.parse('{"name":"Ada","role":"guest","__proto__":{"isAdmin":true}}');
const base = { role: "anonymous" };
const { merged, skipped } = safeMerge(base, payload);
console.log("merged:", JSON.stringify(merged));
console.log("skipped:", skipped.join(","));
console.log("({}).isAdmin:", ({}).isAdmin, "prototype intact:", Object.getPrototypeOf({}) === Object.prototype);
assert.throws(() => strictMerge(base, payload), TypeError);
console.log("strictMerge rejected the payload: TypeError");

// For untrusted keys entirely: a dictionary without prototype involvement.
const registry = Object.create(null);
registry.total = 2;
console.log("null-prototype registry:", registry.total, "own check:", Object.prototype.hasOwnProperty.call(registry, "total"));

// What an unprotected DEEP merge would have done — demonstrated last, on
// purpose: recursion writes into the object that __proto__ resolves to,
// which is Object.prototype itself.
function unsafeDeepMerge(target, source) {
  for (const key of Object.keys(source)) {
    const value = source[key];
    if (value !== null && typeof value === "object") {
      if (typeof target[key] !== "object" || target[key] === null) target[key] = {};
      unsafeDeepMerge(target[key], value);
    } else {
      target[key] = value;
    }
  }
}
unsafeDeepMerge({}, JSON.parse('{"__proto__":{"flag":"polluted"}}'));
console.log("after unsafe deep merge, ({}).flag:", ({}).flag);
console.log("shallow assignment is not enough: recursion is what turns a key into global pollution");
console.log("dependency hygiene: lockfile reviewed, npm audit in CI, majors pinned, no eval on user data");

