// Day 28 — Observability: structured logs, counters, timers.
// Clocks are injected, so the trace is deterministic and testable.
import assert from "node:assert/strict";

function createClock() {
  let t = 1_000;
  return { now: () => t, advance: (ms) => { t += ms; } };
}

function createLogger(now) {
  const emit = (level, msg, fields) => console.log(JSON.stringify({ ts: now(), level, msg, ...fields }));
  return {
    info: (msg, fields = {}) => emit("info", msg, fields),
    error: (msg, fields = {}) => emit("error", msg, fields),
  };
}

function createMetrics() {
  const counters = new Map();
  return {
    inc(name, by = 1) { counters.set(name, (counters.get(name) ?? 0) + by); },
    snapshot: () => Object.fromEntries([...counters.entries()].sort()),
  };
}

function createTimer(now) {
  const started = new Map();
  return {
    start: (id) => { assert(!started.has(id), "timer " + id + " already running"); started.set(id, now()); },
    stop: (id) => { const at = started.get(id); assert(at !== undefined, "timer " + id + " not started"); started.delete(id); return now() - at; },
  };
}

const clock = createClock();
const log = createLogger(clock.now);
const metrics = createMetrics();
const timer = createTimer(clock.now);

function handleRequest(id, cost, outcome) {
  timer.start(id);
  metrics.inc("requests_total");
  clock.advance(cost);
  const took = timer.stop(id);
  if (outcome === "ok") { metrics.inc("requests_ok"); log.info("request done", { id, took_ms: took }); }
  else { metrics.inc("requests_failed"); log.error("request failed", { id, took_ms: took }); }
}

handleRequest("r1", 12, "ok");
handleRequest("r2", 40, "ok");
handleRequest("r3", 7, "fail");
const snap = metrics.snapshot();
console.log("metrics:", JSON.stringify(snap));
assert.deepEqual(snap, { requests_failed: 1, requests_ok: 2, requests_total: 3 });

