// Day 30 — Capstone 2: a task scheduler.
// Priorities, retry budget, concurrency limit and metrics on a virtual clock.
// No timers: every await is a microtask, so the trace is fully deterministic.
import assert from "node:assert/strict";

const LIMIT = 2;

const clock = { t: 0, now: () => clock.t, advance: (ms) => { clock.t += ms; } };
const metrics = { completed: 0, failed: 0, attempts: 0, retries: 0, maxInFlight: 0 };
const journal = [];

// Scripted outcomes per attempt: "ok" | "transient" | "fatal".
const defs = [
  { id: "T1", priority: 2, outcomes: ["ok"] },
  { id: "T2", priority: 1, outcomes: ["transient", "ok"] },
  { id: "T3", priority: 1, outcomes: ["ok"] },
  { id: "T4", priority: 3, outcomes: ["fatal"] },
  { id: "T5", priority: 2, outcomes: ["transient", "transient", "ok"] },
];

function pad(n, width) { return String(n).padStart(width, " "); }

async function execute(job) {
  metrics.attempts += 1;
  journal.push(`t=${pad(clock.t, 2)} start ${job.def.id} (priority ${job.def.priority}, attempt ${job.attempt})`);
  await Promise.resolve(); // stand-in for I/O; keeps the trace deterministic
  const outcome = job.def.outcomes[job.attempt - 1] ?? "fatal";
  await Promise.resolve();
  return outcome;
}

function pickNext(pending) {
  const ready = pending.filter((job) => job.readyAt <= clock.t);
  if (ready.length === 0) return null;
  ready.sort((a, b) => a.def.priority - b.def.priority || a.seq - b.seq);
  return ready[0];
}

async function runScheduler(defs) {
  const pending = defs.map((def, seq) => ({ def, seq, attempt: 0, readyAt: 0 }));
  let running = [];
  while (pending.length > 0 || running.length > 0) {
    while (running.length < LIMIT && pending.length > 0) {
      const job = pickNext(pending);
      if (!job) break;
      pending.splice(pending.indexOf(job), 1);
      job.attempt += 1;
      metrics.maxInFlight = Math.max(metrics.maxInFlight, running.length + 1);
      running.push(execute(job).then((outcome) => ({ job, outcome })));
    }
    if (running.length === 0) {
      const next = Math.min(...pending.map((job) => job.readyAt));
      clock.advance(next - clock.t);
      journal.push(`t=${pad(clock.t, 2)} clock advanced (next work ready)`);
      continue;
    }
    const settled = await Promise.all(running);
    running = [];
    for (const { job, outcome } of settled) {
      if (outcome === "ok") {
        metrics.completed += 1;
        journal.push(`t=${pad(clock.t, 2)} done  ${job.def.id} -> ok`);
      } else if (outcome === "fatal" || job.attempt >= job.def.outcomes.length) {
        metrics.failed += 1;
        journal.push(`t=${pad(clock.t, 2)} done  ${job.def.id} -> ${outcome} (budget spent)`);
      } else {
        metrics.retries += 1;
        const delay = 10 * job.attempt;
        job.readyAt = clock.t + delay;
        pending.push(job);
        journal.push(`t=${pad(clock.t, 2)} done  ${job.def.id} -> transient (retry in ${delay}ms)`);
      }
    }
  }
}

await runScheduler(defs);
for (const line of journal) console.log(line);
console.log(`report: completed=${metrics.completed} failed=${metrics.failed} attempts=${metrics.attempts} retries=${metrics.retries} maxInFlight=${metrics.maxInFlight}`);
assert.deepEqual(metrics, { completed: 4, failed: 1, attempts: 8, retries: 3, maxInFlight: 2 });

